<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileFamilyNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileFamilyNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withFamilyName,
 * getFamilyName/familyName accessors, and isFamilyNameChanged with/without original.
 */
class UserProfileFamilyNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withFamilyName creates a new instance with the FamilyName set
     * from a string value, and getFamilyName returns the primitive string.
     */
    public function testWithFamilyNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileFamilyNameAccessorUnitTest();

        // Act
        $result = $holder->withFamilyName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getFamilyName());
    }
    /**
     * Asserts that withfamilyName has access to the value object
     * from a string value, and getFamilyName returns the primitive string.
     */
    public function testWithFamilyNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileFamilyNameAccessorUnitTest();

        // Act
        $result = $holder->withFamilyName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->familyName()->value());
    }
    public function testChangedFamilyName(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileFamilyNameAccessorUnitTest();
        $original = $holder->withFamilyName('one');
        $same = $holder->withFamilyName('one');
        $modified = $holder->withFamilyName('other');

        // Act
        $unchanged = $holder->isFamilyNameChanged();
        $withSame = $original->isFamilyNameChanged($same);
        $withDiferent = $original->isFamilyNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileFamilyNameAccessorUnitTest
{
    use UserProfileFamilyNameAccessor;
}
